31	/** 1.0 = identical formality; falls off with spread. */
32	export function formalityCoherence(formalities: number[]): number {
33	  const f = formalities.filter((x) => typeof x === "number");
34	  if (f.length < 2) return 1;
35	  const spread = Math.max(...f) - Math.min(...f);
36	  return Math.max(0, 1 - spread / 4); // spread of 4 (1↔5) → 0
37	}
