41	  const harmony = colorHarmonyScore(colors);
42	  const coherence = formalityCoherence(items.map((i) => i.formality ?? 3));
43	  const dnaHits = items.filter((i) => i.style_tags?.some((t) => ctx.aesthetic.includes(t))).length;
44	  const dna = items.length ? dnaHits / items.length : 0;
45	  const base = 0.45 * harmony + 0.35 * coherence + 0.2 * dna;
46	
47	  // With no lean the weight is 0, so scoring is byte-identical to before.
48	  const w = ctx.lean?.length ? LEAN_WEIGHT : 0;
49	  return Math.min(1, base * (1 - w) + w * leanScore(colors, ctx.lean ?? []));
50	}
